export default function Sebastian({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        {/* Stable white paper underneath every paint region. */}
        <rect
          x="0"
          y="0"
          width="1024"
          height="1536"
          fill={PAPER}
          pointerEvents="none"
        />

        {/* Open background area behind the saint and garden scene. */}
        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1024" height="1536" />
        </g>

        {/* Left and right cloud banks. */}
        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} />
        </g>

        {/* Halo field behind the head. */}
        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} />
        </g>

        {/* Shoulder sash and side draped cloth. */}
        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} />
        </g>

        {/* Waist drapery / loincloth and remaining fabric panels. */}
        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} />
        </g>

        {/* Face, torso, arms, hands, and legs. */}
        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} />
        </g>

        {/* Curly hair and brows. */}
        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} />
        </g>

        {/* Three arrows and related arrowhead / shaft details. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} />
        </g>

        {/* Tree, flowers, hedges, cypress, and column scene elements. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} />
        </g>

        {/* Exact traced black line art from the supplied Sebastian image.
            Keep this last and non-interactive so every region remains paintable. */}
        <path
          {...detail}
          {...ink}
          d={SEBASTIAN_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}